STATE_CODES = {
    'Andhra Pradesh': 'AP', 'Arunachal Pradesh': 'AR', 'Assam': 'AS', 'Bihar': 'BR',
    'Chhattisgarh': 'CG', 'Goa': 'GA', 'Gujarat': 'GJ', 'Haryana': 'HR',
    'Himachal Pradesh': 'HP', 'Jharkhand': 'JH', 'Karnataka': 'KA', 'Kerala': 'KL',
    'Madhya Pradesh': 'MP', 'Maharashtra': 'MH', 'Manipur': 'MN', 'Meghalaya': 'ML',
    'Mizoram': 'MZ', 'Nagaland': 'NL', 'Odisha': 'OD', 'Punjab': 'PB',
    'Rajasthan': 'RJ', 'Sikkim': 'SK', 'Tamil Nadu': 'TN', 'Telangana': 'TG',
    'Tripura': 'TR', 'Uttar Pradesh': 'UP', 'Uttarakhand': 'UK', 'West Bengal': 'WB'
}

class Command(BaseCommand):
    help = 'Idempotently seeds all 28 Indian States and their Districts'

    def handle(self, *args, **options):
        self.stdout.write('🌱 Seeding 28 Indian States & Districts...')
        india, _ = Country.objects.get_or_create(name='India', defaults={'iso_code': 'IN', 'is_active': True})

        states_created = 0
        districts_created = 0
        districts_existing = 0

        for state_name, districts_list in ALL_28_STATES_DISTRICTS.items():
            code = STATE_CODES.get(state_name, state_name[:2].upper())
            st = State.objects.filter(name__iexact=state_name).first()

            if not st:
                st, created = State.objects.get_or_create(code=code, defaults={'name': state_name, 'state_code': code, 'country': india, 'is_active': True})
                if created:
                    states_created += 1

            if st.name != state_name or st.country != india or not st.is_active:
                st.name = state_name
                st.country = india
                st.is_active = True
                if not st.state_code:
                    st.state_code = code
                st.save()

            for dist_name in districts_list:
                _, created = District.objects.get_or_create(state=st, name=dist_name, defaults={'is_active': True})
                if created:
                    districts_created += 1
                else:
                    districts_existing += 1

        total_28_states = State.objects.filter(name__in=ALL_28_STATES_DISTRICTS.keys()).count()
        total_districts = District.objects.filter(state__name__in=ALL_28_STATES_DISTRICTS.keys()).count()

        self.stdout.write(self.style.SUCCESS(
            f"✅ Seeding Complete!\n"
            f"   - States Verified/Created: {total_28_states} (New: {states_created})\n"
            f"   - Districts Created: {districts_created}\n"
            f"   - Districts Already Present: {districts_existing}\n"
            f"   - Total Districts Across 28 States: {total_districts}"
        ))
